import React, { useMemo } from 'react'
import { Modal, Alert, Form, Button, Table } from 'react-bootstrap'
import { useI18n } from '../../i18n'

function MealModal({
  show,
  onHide,
  items,
  setItems,
  note,
  setNote,
  eatenAt,
  setEatenAt,
  onAddFood,
  customFoodDraft,
  setCustomFoodDraft,
  onCreateCustomFood,
  creatingCustomFood,
  onSave,
  saving,
  error,
}) {
  const { t, language } = useI18n()
  const totals = useMemo(() => {
    let kcal = 0
    let protein = 0
    let fat = 0
    let carbs = 0
    for (const it of items) {
      kcal += it.kcal_total || 0
      protein += it.protein_total || 0
      fat += it.fat_total || 0
      carbs += it.carbs_total || 0
    }
    return { kcal, protein, fat, carbs }
  }, [items])

  return (
    <Modal show={show} onHide={onHide} centered>
      <Modal.Header closeButton>
        <Modal.Title>{t('addMeal')}</Modal.Title>
      </Modal.Header>

      <Modal.Body>
        {error && <Alert variant="danger">{error}</Alert>}

        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
            <Button variant="outline-info" size="sm" onClick={onAddFood} disabled={!onAddFood}>
              {t('searchFoodUsda')}
            </Button>
          </div>
          <div style={{ opacity: 0.9 }}>
            {t('total')}: {Math.round(totals.kcal)} {t('kcal')} · P {Math.round(totals.protein)} · F {Math.round(totals.fat)} · C{' '}
            {Math.round(totals.carbs)}
          </div>
        </div>

        <div className="mt-3" />

        <div className="chart-card" style={{ padding: 12, marginBottom: 14 }}>
          <div style={{ fontWeight: 600, marginBottom: 8 }}>{t('addCustomFood')}</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
            <Form.Control
              placeholder={t('foodNameRequired')}
              value={customFoodDraft?.name || ''}
              onChange={(e) => setCustomFoodDraft && setCustomFoodDraft((p) => ({ ...p, name: e.target.value }))}
            />
            <Form.Control
              placeholder={t('brandOptional')}
              value={customFoodDraft?.brand || ''}
              onChange={(e) => setCustomFoodDraft && setCustomFoodDraft((p) => ({ ...p, brand: e.target.value }))}
            />
            <Form.Control
              type="number"
              inputMode="decimal"
              placeholder={t('kcalPer100g')}
              value={customFoodDraft?.kcal_per_100g || ''}
              onChange={(e) =>
                setCustomFoodDraft && setCustomFoodDraft((p) => ({ ...p, kcal_per_100g: e.target.value }))
              }
            />
            <Form.Control
              type="number"
              inputMode="decimal"
              placeholder={t('proteinPer100g')}
              value={customFoodDraft?.protein_per_100g || ''}
              onChange={(e) =>
                setCustomFoodDraft && setCustomFoodDraft((p) => ({ ...p, protein_per_100g: e.target.value }))
              }
            />
            <Form.Control
              type="number"
              inputMode="decimal"
              placeholder={t('fatPer100g')}
              value={customFoodDraft?.fat_per_100g || ''}
              onChange={(e) =>
                setCustomFoodDraft && setCustomFoodDraft((p) => ({ ...p, fat_per_100g: e.target.value }))
              }
            />
            <Form.Control
              type="number"
              inputMode="decimal"
              placeholder={t('carbsPer100g')}
              value={customFoodDraft?.carbs_per_100g || ''}
              onChange={(e) =>
                setCustomFoodDraft && setCustomFoodDraft((p) => ({ ...p, carbs_per_100g: e.target.value }))
              }
            />
          </div>
          <div style={{ marginTop: 10 }}>
            <Button
              size="sm"
              variant="info"
              onClick={() => onCreateCustomFood && onCreateCustomFood()}
              disabled={!onCreateCustomFood || creatingCustomFood || !(customFoodDraft?.name || '').trim()}
            >
              {creatingCustomFood ? t('creating') : t('createAndAdd')}
            </Button>
          </div>
        </div>

        <Form.Group className="mb-3">
          <Form.Label>{t('eatenAt')}</Form.Label>
          <Form.Control
            type="datetime-local"
            lang={language}
            value={eatenAt}
            onChange={(e) => setEatenAt && setEatenAt(e.target.value)}
            
          />
        </Form.Group>

        <Table bordered hover responsive size="sm">
          <thead>
            <tr>
              <th>{t('item')}</th>
              <th style={{ width: 120 }}>{t('grams')}</th>
              <th style={{ width: 90 }}>kcal</th>
              <th style={{ width: 90 }}>P</th>
              <th style={{ width: 90 }}>F</th>
              <th style={{ width: 90 }}>C</th>
              <th style={{ width: 80 }} />
            </tr>
          </thead>
          <tbody>
            {items.length === 0 ? (
              <tr>
                <td colSpan={7} style={{ opacity: 0.8 }}>
                  {t('noFoodsAddedYet')}
                </td>
              </tr>
            ) : (
              items.map((it, idx) => (
                <tr key={`${it.food_id}-${idx}`}>
                  <td>{it.name_snapshot}</td>
                  <td>
                    <Form.Control
                      type="number"
                      inputMode="decimal"
                      value={it.grams}
                      onChange={(e) => {
                        const grams = e.target.value
                        const g = Number(grams || 0)
                        const factor = g / 100
                        setItems((prev) =>
                          prev.map((p, i) =>
                            i === idx
                              ? {
                                  ...p,
                                  grams,
                                  kcal_total: (p.kcal_per_100g || 0) * factor,
                                  protein_total: (p.protein_per_100g || 0) * factor,
                                  fat_total: (p.fat_per_100g || 0) * factor,
                                  carbs_total: (p.carbs_per_100g || 0) * factor,
                                }
                              : p
                          )
                        )
                      }}
                    />
                  </td>
                  <td>{Math.round(it.kcal_total || 0)}</td>
                  <td>{Math.round(it.protein_total || 0)}</td>
                  <td>{Math.round(it.fat_total || 0)}</td>
                  <td>{Math.round(it.carbs_total || 0)}</td>
                  <td>
                    <Button
                      size="sm"
                      variant="outline-light"
                      onClick={() => setItems((prev) => prev.filter((_, i) => i !== idx))}
                    >
                      {t('remove')}
                    </Button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </Table>

        <Form.Group>
          <Form.Label>{t('noteOptional')}</Form.Label>
          <Form.Control value={note} onChange={(e) => setNote(e.target.value)} placeholder={t('notePlaceholder')} />
        </Form.Group>
      </Modal.Body>

      <Modal.Footer>
        <Button variant="secondary" onClick={onHide}>
          {t('cancel')}
        </Button>
        <Button variant="info" onClick={onSave} disabled={!onSave || saving || items.length === 0}>
          {saving ? t('saving') : t('save')}
        </Button>
      </Modal.Footer>
    </Modal>
  )
}

export default MealModal
